-- Monthly invoice revenue by payment type (Cash = contract AD_CASH_CONTRACT or invoice type C/D, Credit = R),
-- pharmacy split, visits (episodes) and refunds. Ties to NextGen [Total Revenue] within 0.01 %.
-- {P} = schema prefix ('EXSYS.' when the connection user is not the owner, '' otherwise); {D0}/{D1} = 'YYYY-MM-DD'.
-- Split long ranges (>= 30 months on a big branch) into chunks: the Cure MCP device call times out at 60 s.
SELECT YM||';'||ROUND(SUM(CASE WHEN PT IN ('C','D') AND PH='N' THEN NET ELSE 0 END))||';'||ROUND(SUM(CASE WHEN PT IN ('C','D') AND PH='Y' THEN NET ELSE 0 END))||';'||ROUND(SUM(CASE WHEN PT='R' AND PH='N' THEN NET ELSE 0 END))||';'||ROUND(SUM(CASE WHEN PT='R' AND PH='Y' THEN NET ELSE 0 END))||';'||ROUND(SUM(CASE WHEN PT NOT IN ('C','D','R') THEN NET ELSE 0 END))||';'||SUM(CASE WHEN PT IN ('C','D') THEN EPS ELSE 0 END)||';'||SUM(CASE WHEN PT='R' THEN EPS ELSE 0 END)||';'||ROUND(SUM(CASE WHEN PT IN ('C','D') THEN RF ELSE 0 END))||';'||ROUND(SUM(CASE WHEN PT='R' THEN RF ELSE 0 END)) R
FROM (
 SELECT TO_CHAR(M.PATIENT_INVOICE_DATE,'YYYYMM') YM,
        DECODE(E.CONTRACT_NO, TO_NUMBER({P}GET_PARAMETER('AD_CASH_CONTRACT')),'C',M.PATIENT_INVOICE_TYPE) PT,
        CASE WHEN CS.DESCRIPTION_P='Pharmacy' THEN 'Y' ELSE 'N' END PH,
        SUM(NVL(C.BILL_AMOUNT,0)-NVL(C.BILL_DISCOUNT,0)-NVL(C.VAT_AMT,0)-DECODE(C.BILL_TO,'P',0,NVL(C.BILL_PATIENT_SHARE,0))) NET,
        COUNT(DISTINCT M.PATIENT_FILE_NO||'-'||M.EPISODE_NO) EPS, 0 RF
 FROM {P}RC_PATIENT_INVOICES M, {P}RC_PATIENT_INVOICE_CHARGES C, {P}RC_PATIENT_EPISODES E, {P}RC_SERVICES S, {P}RC_CLINICAL_SPECIALITIES CS
 WHERE E.PATIENT_FILE_NO=M.PATIENT_FILE_NO AND E.ORGANIZATION_NO=M.ORGANIZATION_NO AND E.EPISODE_NO=M.EPISODE_NO
   AND M.ORGANIZATION_NO=C.ORGANIZATION_NO AND M.PATIENT_INVOICE_NO=C.PATIENT_INVOICE_NO
   AND C.PRODUCT_CODE=S.PRODUCT_CODE AND S.SPECIALTY_NO=CS.SPECIALTY_NO
   AND M.STATUS='P' AND C.STATUS='P' AND C.BILL_TO IN ('C','G','P')
   AND M.PATIENT_INVOICE_DATE>=DATE '{D0}' AND M.PATIENT_INVOICE_DATE<DATE '{D1}'
 GROUP BY TO_CHAR(M.PATIENT_INVOICE_DATE,'YYYYMM'), DECODE(E.CONTRACT_NO, TO_NUMBER({P}GET_PARAMETER('AD_CASH_CONTRACT')),'C',M.PATIENT_INVOICE_TYPE), CASE WHEN CS.DESCRIPTION_P='Pharmacy' THEN 'Y' ELSE 'N' END
 UNION ALL
 SELECT TO_CHAR(R.REFUND_INVOICE_DATE,'YYYYMM'),
        DECODE(E.CONTRACT_NO, TO_NUMBER({P}GET_PARAMETER('AD_CASH_CONTRACT')),'C',M.PATIENT_INVOICE_TYPE),
        CASE WHEN CS.DESCRIPTION_P='Pharmacy' THEN 'Y' ELSE 'N' END,
        -SUM(NVL(C.BILL_AMOUNT,0)-NVL(C.BILL_DISCOUNT,0)-NVL(C.VAT_AMT,0)-DECODE(C.BILL_TO,'P',0,NVL(C.BILL_PATIENT_SHARE,0))), 0,
        -SUM(NVL(C.BILL_AMOUNT,0)-NVL(C.BILL_DISCOUNT,0)-NVL(C.VAT_AMT,0)-DECODE(C.BILL_TO,'P',0,NVL(C.BILL_PATIENT_SHARE,0)))
 FROM {P}RC_PATIENT_REFUND_INVOICES R, {P}RC_PATIENT_RETURN_INV_CHARGES C, {P}RC_PATIENT_INVOICES M, {P}RC_PATIENT_EPISODES E, {P}RC_SERVICES S, {P}RC_CLINICAL_SPECIALITIES CS
 WHERE R.ORGANIZATION_NO=M.ORGANIZATION_NO AND R.PATIENT_INVOICE_NO=M.PATIENT_INVOICE_NO
   AND E.PATIENT_FILE_NO=M.PATIENT_FILE_NO AND E.ORGANIZATION_NO=M.ORGANIZATION_NO AND E.EPISODE_NO=M.EPISODE_NO
   AND R.ORGANIZATION_NO=C.ORGANIZATION_NO AND R.REFUND_INVOICE_NO=C.REFUND_INVOICE_NO
   AND C.PRODUCT_CODE=S.PRODUCT_CODE AND S.SPECIALTY_NO=CS.SPECIALTY_NO
   AND M.STATUS='P' AND C.STATUS='P' AND R.STATUS='P' AND C.BILL_TO IN ('C','G','P')
   AND R.REFUND_INVOICE_DATE>=DATE '{D0}' AND R.REFUND_INVOICE_DATE<DATE '{D1}'
 GROUP BY TO_CHAR(R.REFUND_INVOICE_DATE,'YYYYMM'), DECODE(E.CONTRACT_NO, TO_NUMBER({P}GET_PARAMETER('AD_CASH_CONTRACT')),'C',M.PATIENT_INVOICE_TYPE), CASE WHEN CS.DESCRIPTION_P='Pharmacy' THEN 'Y' ELSE 'N' END
) GROUP BY YM ORDER BY 1
-- Output per line: YM;cash_np;cash_ph;credit_np;credit_ph;other;eps_cash;eps_credit;refund_cash;refund_credit  (net already includes refunds)
